var index_default = app;
var server = process.env.VERCEL ? null : app.listen(PORT, "127.0.0.1", () => {
  console.log(`[api] PLAYFLIX API listening on http://127.0.0.1:${PORT} using ${db.label}`);
});
async function shutdown(signal) {
  if (!server) return;
  console.log(`[api] ${signal}, shutting down`);
  server.close(async () => {
    await closeDatabase();
    process.exit(0);
  });
}
if (server) {
  process.on("SIGINT", () => void shutdown("SIGINT"));
  process.on("SIGTERM", () => void shutdown("SIGTERM"));
}

// server/vercel-entry.ts
var config = { api: { bodyParser: false } };
function handler(req, res) {
  const raw = req.url ?? "/";
  const [pathname, search = ""] = raw.split("?");
  const params = new URLSearchParams(search);
  const forwardedPath = params.get("path");
  if (forwardedPath != null) {
    params.delete("path");
    const rest = params.toString();
    req.url = `/v1/${forwardedPath}${rest ? `?${rest}` : ""}`;
  } else if (pathname.startsWith("/api/v1/")) {
    req.url = pathname.slice(4) + (search ? `?${search}` : "");
  } else if (pathname === "/api/v1" || pathname === "/api/index") {
    req.url = "/v1";
  }
  index_default(req, res);
}
export {
  config,
  handler as default
};
